@import url('https://fonts.googleapis.com/css2?family=Staatliches&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Bayern Munich DNA — deep red command, bavarian lozenges, mia san mia */
.theme-bayern-munich {
  --bg: oklch(0.418 0.158 20.7);
  --surface: oklch(0.454 0.172 21.0);
  --surface-2: oklch(0.497 0.183 20.2);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.794 0.068 7.1);
  --accent: oklch(1.000 0 0);
  --accent-fg: oklch(0.418 0.158 20.7);
  --accent-2: oklch(0.503 0.144 250.3);
  --line: oklch(1 0 0 / 22%);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.55 0.2 27);
  --radius: 0.375rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Staatliches", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-bayern-munich h1,
.theme-bayern-munich h2,
.theme-bayern-munich h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-bayern-munich { --font-ui: var(--font-display); }
.theme-bayern-munich h1, .theme-bayern-munich h2 { text-transform: uppercase; }
.theme-bayern-munich button { text-transform: uppercase; letter-spacing: 0.06em; }

.theme-bayern-munich { background-image: repeating-linear-gradient(45deg, oklch(1 0 0 / 4%) 0 26px, transparent 26px 52px), repeating-linear-gradient(-45deg, oklch(1 0 0 / 4%) 0 26px, transparent 26px 52px); }
.theme-bayern-munich h1 { letter-spacing: 0.04em; }
.theme-bayern-munich .label-caps { color: oklch(0.9 0.02 250); }

/* depth */
.theme-bayern-munich thead th { background: oklch(0.36 0.145 21); color: oklch(1 0 0); text-transform: uppercase; letter-spacing: 0.1em; font-size: 0.78em; border-bottom: 2px solid oklch(0.62 0.13 250); }
.theme-bayern-munich td { border-bottom: 1px solid var(--line); }
.theme-bayern-munich tbody tr:hover { background: oklch(1 0 0 / 8%); }
.theme-bayern-munich a { color: oklch(1 0 0); text-underline-offset: 3px; text-decoration-color: oklch(0.70 0.12 250); }
.theme-bayern-munich a:hover { text-decoration-thickness: 2px; }
.theme-bayern-munich ::selection { background: oklch(1 0 0); color: oklch(0.418 0.158 20.7); }
.theme-bayern-munich input, .theme-bayern-munich select, .theme-bayern-munich textarea { background: oklch(0.37 0.145 21); border-color: var(--line); color: oklch(1 0 0); }
.theme-bayern-munich input:focus-visible, .theme-bayern-munich select:focus-visible, .theme-bayern-munich textarea:focus-visible { outline: 2px solid oklch(1 0 0); outline-offset: 1px; }
.theme-bayern-munich kbd { background: oklch(0.36 0.145 21); border: 1px solid var(--line); border-bottom: 3px solid oklch(0.62 0.13 250); border-radius: var(--radius-sm); padding: 0.1em 0.45em; font-family: var(--font-mono); }
.theme-bayern-munich ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-bayern-munich ::-webkit-scrollbar-track { background: oklch(0.36 0.145 21); }
.theme-bayern-munich ::-webkit-scrollbar-thumb { background: oklch(1 0 0 / 75%); border-radius: 5px; border: 2px solid oklch(0.36 0.145 21); }
.theme-bayern-munich ::-webkit-scrollbar-thumb:hover { background: oklch(1 0 0); }
/* bavarian lozenges woven into the frame */
.theme-bayern-munich .themed-border { border-image: repeating-linear-gradient(45deg, oklch(0.62 0.13 250) 0 12px, oklch(1 0 0) 12px 24px) 1; }
.theme-bayern-munich button:active { transform: translateY(1px); }

/* alt mode: away kit (2026-27 real kit / NBA Association Edition) */
.theme-bayern-munich.alt-mode {
  --bg: oklch(0.988 0 0);
  --surface: oklch(1.000 0 0);
  --surface-2: oklch(0.955 0.006 264.5);
  --fg: oklch(0.284 0.072 259.1);
  --fg-muted: oklch(0.560 0.039 261.8);
  --accent: oklch(0.284 0.072 259.1);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.565 0.227 23.3);
  --line: oklch(0.915 0.010 261.8);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
}
.theme-bayern-munich.alt-mode { background-image: none; }
.theme-bayern-munich.alt-mode a { color: var(--fg); text-decoration-color: #dc052d; }
.theme-bayern-munich.alt-mode input, .theme-bayern-munich.alt-mode select, .theme-bayern-munich.alt-mode textarea { background: oklch(1 0 0); border-color: var(--line); color: var(--fg); }
.theme-bayern-munich.alt-mode input:focus-visible, .theme-bayern-munich.alt-mode select:focus-visible, .theme-bayern-munich.alt-mode textarea:focus-visible { outline: 2px solid oklch(0.284 0.072 259.1); }
.theme-bayern-munich.alt-mode kbd { background: var(--surface-2); color: var(--fg); border-color: var(--line); }
.theme-bayern-munich.alt-mode thead th { background: oklch(0.284 0.072 259.1); border-bottom-color: #dc052d; }
.theme-bayern-munich.alt-mode tbody tr:hover { background: oklch(0.284 0.072 259.1 / 7%); }
.theme-bayern-munich.alt-mode ::selection { background: oklch(0.284 0.072 259.1); color: oklch(1 0 0); }
.theme-bayern-munich.alt-mode ::-webkit-scrollbar-track { background: var(--surface-2); }
.theme-bayern-munich.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0.284 0.072 259.1 / 70%); border-color: var(--surface-2); }
.theme-bayern-munich.alt-mode ::-webkit-scrollbar-thumb:hover { background: oklch(0.284 0.072 259.1); }
.theme-bayern-munich.alt-mode .themed-border { border-image: repeating-linear-gradient(45deg, #12294d 0 12px, #dc052d 12px 24px) 1; }
.theme-bayern-munich.alt-mode h1::after { content: ""; display: block; height: 6px; width: 6rem; margin-top: 0.6rem; background: linear-gradient(90deg, #12294d 0 33%, #dc052d 33% 66%, #12294d 66% 100%); }
.theme-bayern-munich.alt-mode .label-caps { color: #dc052d; }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-app, var(--font-display));
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-app, var(--font-display)) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
